/**
 * Fastify application factory.
 *
 * Exposes a single `buildApp(config)` entry point so tests can `inject()`
 * requests without binding a TCP port. The full route table will grow with
 * subsequent tasks; the only handler that exists today is the `/api/health`
 * smoke check required by TASK-68.
 */
import Fastify, { type FastifyInstance } from "fastify";
import type { ServerConfig } from "./config.js";

export interface BuildAppOptions {
  /** Disable Fastify's startup logger (useful in tests). */
  quietLogger?: boolean;
}

/**
 * Construct a Fastify instance with the Drift baseline:
 *  - JSON body parser enabled (consumed by future REST handlers).
 *  - `/api/health` route returning `{ ok: true, galaxySeed }`.
 *
 * The function is intentionally side-effect free: it does NOT call
 * `app.listen()`. The entrypoint (`src/server/index.ts`) is responsible
 * for binding to a TCP port.
 */
export async function buildApp(
  config: ServerConfig,
  options: BuildAppOptions = {},
): Promise<FastifyInstance> {
  const app = Fastify({
    logger: options.quietLogger ? false : { level: process.env.LOG_LEVEL ?? "info" },
  });

  app.get("/api/health", async () => ({
    ok: true,
    galaxySeed: config.galaxySeed,
  }));

  return app;
}

/**
 * Drift server entry point.
 *
 * Reads config from `.env.local`, builds the Fastify app, attaches the
 * WebSocket server, and listens on `config.apiPort` (defaults to
 * `config.port + 1` so the Fastify server and the Vite dev server don't
 * collide on `PORT=3000`). `tsx watch` invokes this file during
 * `npm run dev`; production launches it via `node dist/server/index.js`
 * (TASK-69).
 *
 * Graceful shutdown closes both the HTTP server and the ws handle so the
 * process exits cleanly when killed by `tsx`/CI.
 */
import { serverConfig } from "./config.js";
import { buildApp } from "./server.js";
import { attachWs } from "./ws.js";

async function main(): Promise<void> {
  const app = await buildApp(serverConfig);
  const ws = attachWs(app, serverConfig.wsPath);

  await app.listen({ port: serverConfig.apiPort, host: "0.0.0.0" });
  app.log.info(
    { port: serverConfig.apiPort, wsPath: serverConfig.wsPath, clientPort: serverConfig.port },
    "drift server listening",
  );

  const shutdown = async (signal: string): Promise<void> => {
    app.log.info({ signal }, "shutting down");
    try {
      await ws.close();
      await app.close();
    } finally {
      process.exit(0);
    }
  };

  process.on("SIGINT", () => void shutdown("SIGINT"));
  process.on("SIGTERM", () => void shutdown("SIGTERM"));
}

main().catch((err: unknown) => {
  // Surface the error then exit with a non-zero code so `tsx watch` respawns.
  console.error("[drift-server] fatal:", err);
  process.exit(1);
});

